&reftitle.description;
public mixedPDOStatement::fetch intmodePDO::FETCH_DEFAULT intcursorOrientationPDO::FETCH_ORI_NEXT intcursorOffset0
PDOStatement インスタンスに関連付けられた結果セットから1行取得します。 mode パラメータは、PDO がその行をどの様に返すかを決定します。

&reftitle.returnvalues;

 この関数が成功した場合の戻り値は、取得形式によって異なります。
 失敗した場合、または行が残っていない場合は、常に &false; を返します。

  &reftitle.examples;

   異なる取得方法で行を取得する


<?php
$db = new PDO('sqlite::memory:');
$db->exec("CREATE TABLE fruit (name VARCHAR(100), colour VARCHAR(100))");
$db->exec("INSERT INTO fruit (name, colour) VALUES
                             ('apple', 'red'),
                             ('banana', 'yellow'),
                             ('orange', 'orange'),
                             ('kiwi', 'green')");
$sth = $db->prepare("SELECT name, colour FROM fruit");
$sth->execute();

/* Exercise PDOStatement::fetch styles */
echo "PDO::FETCH_ASSOC: ";
echo "Return next row as an array indexed by column name\n";
$result = $sth->fetch(PDO::FETCH_ASSOC);
var_dump($result);
echo "\n";

echo "PDO::FETCH_BOTH: ";
echo "Return next row as an array indexed by both column name and number\n";
$result = $sth->fetch(PDO::FETCH_BOTH);
var_dump($result);
echo "\n";

echo "PDO::FETCH_LAZY: ";
echo "Return next row as a PDORow object with column names as properties\n";
$result = $sth->fetch(PDO::FETCH_LAZY);
var_dump($result);
echo "\n";

echo "PDO::FETCH_OBJ: ";
echo "Return next row as an stdClass object with column names as properties\n";
$result = $sth->fetch(PDO::FETCH_OBJ);
var_dump($result);
echo "\n";
?>


   &example.outputs;


PDO::FETCH_ASSOC: Return next row as an array indexed by column name
array(2) {
  ["name"]=>
  string(5) "apple"
  ["colour"]=>
  string(3) "red"
}

PDO::FETCH_BOTH: Return next row as an array indexed by both column name and number
array(4) {
  ["name"]=>
  string(6) "banana"
  [0]=>
  string(6) "banana"
  ["colour"]=>
  string(6) "yellow"
  [1]=>
  string(6) "yellow"
}

PDO::FETCH_LAZY: Return next row as a PDORow object with column names as properties
object(PDORow)#3 (3) {
  ["queryString"]=>
  string(30) "SELECT name, colour FROM fruit"
  ["name"]=>
  string(6) "orange"
  ["colour"]=>
  string(6) "orange"
}

PDO::FETCH_OBJ: Return next row as an stdClass object with column names as properties
object(stdClass)#4 (2) {
  ["name"]=>
  string(4) "kiwi"
  ["colour"]=>
  string(5) "green"
}





   スクロール可能なカーソルで行を取得する


<?php
function readDataForwards($dbh) {
    $sql = 'SELECT hand, won, bet FROM mynumbers ORDER BY BET';
    $stmt = $dbh->prepare($sql, array(PDO::ATTR_CURSOR => PDO::CURSOR_SCROLL));
    $stmt->execute();
    while ($row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_NEXT)) {
        $data = $row[0] . "\t" . $row[1] . "\t" . $row[2] . "\n";
        print $data;
    }
}
function readDataBackwards($dbh) {
    $sql = 'SELECT hand, won, bet FROM mynumbers ORDER BY bet';
    $stmt = $dbh->prepare($sql, array(PDO::ATTR_CURSOR => PDO::CURSOR_SCROLL));
    $stmt->execute();
    $row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_LAST);
    do {
        $data = $row[0] . "\t" . $row[1] . "\t" . $row[2] . "\n";
        print $data;
    } while ($row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_PRIOR));
}

print "Reading forwards:\n";
readDataForwards($conn);

print "Reading backwards:\n";
readDataBackwards($conn);
?>


   &example.outputs;


Reading forwards:
21    10    5
16    0     5
19    20    10

Reading backwards:
19    20    10
16    0     5
21    10    5





   構築の順序

    PDO::FETCH_CLASS でオブジェクトを取得するときには、
    まずオブジェクトのプロパティへの代入を終えてから、そのクラスのコンストラクタを実行します。
    PDO::FETCH_PROPS_LATE を指定した場合はこの順序が逆転します。
    つまり、まずコンストラクタを呼び出してから、プロパティへの代入を行います。



<?php
class Person
{
    private $name;

    public function __construct()
    {
        $this->tell();
    }

    public function tell()
    {
        if (isset($this->name)) {
            echo "I am {$this->name}.\n";
        } else {
            echo "I don't have a name yet.\n";
        }
    }
}

$sth = $dbh->query("SELECT * FROM people");
$sth->setFetchMode(PDO::FETCH_CLASS, 'Person');
$person = $sth->fetch();
$person->tell();
$sth->setFetchMode(PDO::FETCH_CLASS|PDO::FETCH_PROPS_LATE, 'Person');
$person = $sth->fetch();
$person->tell();
?>


   &example.outputs.similar;


I am Alice.
I am Alice.
I don't have a name yet.
I am Bob.
